{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history shows positive bias (e.g., >0.00) and model overestimates prices.",
    "Reduce forecast magnitude by 5-10% if recent true outcomes show mean reversion toward lower levels after a spike.",
    "Increase forecast sensitivity to recent low prices when sentiment is neutral or negative (e.g., 0.00 or -0.25).",
    "Apply lag correction: if true outcome is significantly lower than forecast, adjust next period’s forecast downward by 3-5% to account for delayed market reaction.",
    "Avoid overshoot after sharp price spikes: if model forecasts a spike followed by a sharp drop, reduce peak forecast by 10-15% to prevent overcorrection.",
    "When sentiment history includes multiple 0.00 entries, assume market is consolidating — use median of recent 5-day true outcomes as baseline for next forecast."
  ]
}
